#!/usr/bin/env python3
"""Generate offline UI content and Markdown from one reviewed English guide."""
import argparse,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def outputs():
 data=json.loads((ROOT/'docs/guide.json').read_text());data['features']=json.loads((ROOT/'docs/features.json').read_text());lines=['# '+data['title'],'','Version '+data['version']+' · Initial open-source release · [About and credits](../NOTICE.md)','','This guide is also available in the dashboard sidebar under **User Guide**. Installation prerequisites are in [INSTALLATION.md](INSTALLATION.md). Read [Feature availability](SUPPORTED_FEATURES.md) for precise status/limits and [PDF manuals](MANUALS.md) for the English/Arabic books.','']
 for i,s in enumerate(data['sections'],1):lines.append('- ['+str(i)+'. '+s['title']+'](#'+s['id']+')')
 for i,s in enumerate(data['sections'],1):
  lines+=['','<a id="'+s['id']+'"></a>','','## '+str(i)+'. '+s['title'],'','**Where:** '+s['where'],'']
  for p in s['paragraphs']:lines += [p,'']
  for i,p in enumerate(s['steps'],1):lines.append(str(i)+'. '+p)
  if s['limit']:lines+=['','**Limit:** '+s['limit'],'']
 support=['# Feature availability and boundaries','','Generated from `docs/features.json`. This describes the dashboard integration, not every capability of upstream PC². A setting does not install its external runtime.','','**Status key:** Available = integrated controls within the stated limits; Read-only = inspection only; Partly supported = only the listed scope; Requires external setup = separately deployed services; Not yet validated = no deployment certification; Unavailable = not provided here.','','| Feature | Status | What works | Limits / next step |','| --- | --- | --- | --- |']
 for f in data['features']:support.append('| '+' | '.join(str(v).replace('|','\\|').replace('\n',' ') for v in (f['label'],f['status'],f['works'],f['limits']+' '+f['alternative']))+' |')
 support+=['','See [Installation](INSTALLATION.md), [Roadmap](ROADMAP.md) and [User Guide](USER_GUIDE.md). A local regression pass does not certify every host, LAN or load.']
 return {ROOT/'docs/USER_GUIDE.md':'\n'.join(lines)+'\n',ROOT/'docs/SUPPORTED_FEATURES.md':'\n'.join(support)+'\n',ROOT/'lcpc/admin-ui/guide-content.js':'/* Generated by tools/build-guide.py. Edit docs/guide.json and docs/features.json. */\n(()=>{const data='+json.dumps(data,ensure_ascii=True,separators=(',',':'))+';if(typeof module!=="undefined"&&module.exports)module.exports=data;else window.LCPCGuideContent=data;})();\n'}
if __name__=='__main__':
 parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');args=parser.parse_args()
 for file,text in outputs().items():
  if args.check:
   if not file.exists() or file.read_text()!=text:raise SystemExit('Stale generated guide: '+str(file.relative_to(ROOT)))
  else:file.write_text(text)
